/**
 * Color filtering uses subset semantics for "include": a commander passes only
 * if its entire colour identity is contained within the included colours. An
 * empty (colourless) identity is a subset of any set, so colourless commanders
 * always pass a colour include. "Exclude" is unchanged: dropping any identity
 * that touches an excluded colour at all.
 */
function matchesColors(suggestion: CommanderSuggestionDTO, selection: FilterSelection): boolean {
  const { include, exclude } = selection;
  if (include.length > 0) {
    const allowed = new Set(include);
    if (!suggestion.colorIdentity.some((color) => allowed.has(color))) return false;
  }
  if (exclude.length > 0) {
    const excluded = new Set(exclude);
    if (suggestion.colorIdentity.some((color) => excluded.has(color))) return false;
  }
  return true;
}

